pub use rt::ultimate_combat::ClassTableRow;
pub use rt::ultimate_combat::UcClassId;
pub fn class_chassis_resolve(
    class_id: UcClassId,
    level: u8,
    rule_set: crate::rules_core::rules_catalog::RuleSetId,
) -> Option<ClassTableRow> {
    if rule_set != crate::rules_core::rules_catalog::RuleSetId::Uc {
        return None;
    }
    match class_id {
        UcClassId::Gunslinger => class_gunslinger::class_table()
            .into_iter()
            .find(|row| row.level == level),
        UcClassId::Ninja => class_ninja::class_table()
            .into_iter()
            .find(|row| row.level == level),
        UcClassId::Samurai => class_samurai::class_table()
            .into_iter()
            .find(|row| row.level == level),
    }
}
